class color32
{
public:
  unsigned int value;
};

struct WavePositionHint
{
  char data[0x21C];
};

struct po
{
  float data[16];
} __attribute__((aligned(16)));

class beach_object
{
  char data[0x3C];

public:
  void get_settings (const beach_object& obj);
};

class water_object : public beach_object
{
public:
  void get_settings (const water_object& obj);

protected:
  color32 ren_col;
  float my_max_alpha;
  WavePositionHint wave_hint;
  bool use_hint;
  po my_initial_po;
  bool grindable;
  float fade_distance;
};

// only implemented for water_objects right now
void water_object::get_settings (const water_object& obj)
{
  ren_col = obj.ren_col;
  wave_hint = obj.wave_hint;
  use_hint = obj.use_hint;
  my_initial_po = obj.my_initial_po;
  grindable = obj.grindable;
  fade_distance = obj.fade_distance;

  beach_object::get_settings (obj);
}
